import { useEffect, useRef } from "react";
import { Map, useKakaoLoader as useKakaoLoaderOrigin } from "react-kakao-maps-sdk";

const CardItem_Map = (mapx,mapy,mlevel) => {

    //스크립트로 api가져오면 window전역객체로 분류.
    // 함수형 컴포넌트에서는 인식 못함 -> 때문에 변수선언.
    
    //console.log(mapx);
    //console.log(mapy);
    //console.log(mlevel);

    const useKakaoLoader = () => {
        useKakaoLoaderOrigin({
          /** 
       * ※Caution ※ In the case of appkey, you have to use your own appkey.
       * This key is issued for docs and should not be used arbitrarily.
       * 
       * @참고 https://apis.map.kakao.com/web/guide/
       */
          appkey: "6ec8020798deac7ef2f8897ad1c5ccf1",
          libraries: ["clusterer", "drawing", "services"],
        })
      }



    
    return (
        <div className="cardItemMap">
            <Map 
                id = "map"
                //center = {{lat : mapx, lng : mapy}}
                center = {{lat : 127.0642637521, lng : 37.6449411189}}
                level = {3}
                style = {{width:'300px', height:"300px"}}
             />            
        </div>
    );
}


export default CardItem_Map;
